// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseTokenArg,
        address nftArg,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public {
        // keep parameters admissible: distinct tokens, valid reserves, valid fee rate
        vm.assume(baseTokenArg != address(0));
        vm.assume(nftArg != address(0));
        vm.assume(baseTokenArg != nftArg);
        vm.assume(vNft > vBase); // reserves consistent for a buy-side AMM
        vm.assume(feeRate <= 5_000);

        c.initialize(
            baseTokenArg,
            nftArg,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        );

        // general rule: baseToken always stores the base token argument
        assertTrue(c.baseToken() == baseTokenArg);
    }
}
